-- Section 109 — Democracy & Power Band 5 Sprint
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Kan demokrati fungere uden befolkningens tillid til institutioner — og hvad sker der med demokratiet når tilliden eroderer?","options":["Tillid er demokratiets fundamentale forudsætning: demokratiske institutioner kræver frivillig accept af tabte valg, domstolenes afgørelser og mediernes rolle. Når tilliden eroderer opstår der en ond cirkel: mistillid fører til polarisering, polarisering underminerer institutioner, og institutionel svækkelse bekræfter mistilliden — en dynamik der historisk har ført til demokratisk backsliding","Demokrati kan fungere fint uden tillid fordi tvangsmagt og formelle regler er tilstrækkelige til at håndhæve demokratiske processer uanset befolkningens holdning","Tillid er udelukkende et kulturelt fænomen uden politisk betydning for demokratiets funktionsevne — institutioner virker uafhængigt af om borgerne stoler på dem","Demokratier med lav institutionel tillid er faktisk mere levende fordi kritisk mistillid skærper kontrolmekanismerne og holder magthavere på tæerne"],"correct":"Tillid er demokratiets fundamentale forudsætning: demokratiske institutioner kræver frivillig accept af tabte valg, domstolenes afgørelser og mediernes rolle. Når tilliden eroderer opstår der en ond cirkel: mistillid fører til polarisering, polarisering underminerer institutioner, og institutionel svækkelse bekræfter mistilliden — en dynamik der historisk har ført til demokratisk backsliding","accepted_answers":["Tillid er demokratiets fundamentale forudsætning: demokratiske institutioner kræver frivillig accept af tabte valg, domstolenes afgørelser og mediernes rolle. Når tilliden eroderer opstår der en ond cirkel: mistillid fører til polarisering, polarisering underminerer institutioner, og institutionel svækkelse bekræfter mistilliden — en dynamik der historisk har ført til demokratisk backsliding"],"review_text":"Robert Putnams social capital-forskning viser at civic trust er afgørende for demokratisk performance. Institutioners legitimitet er afhængig af befolkningens frivillige accept — formelle regler kan overleve med lav tillid på kort sigt, men den onde cirkel-dynamik er empirisk dokumenteret. I Ungarn og Polen har systematisk institutionel delegitimering via 'rigged system'-retorik svækket tilliden til valgresultater, domstole og medier. Tillid er ikke et supplement til demokratisk arkitektur — det er demokratiets usynlige fundament. Uden det kan valg afholdes, men det fælles forpligtende fundament der gør tabere til loyale opposition frem for fjender er fraværende."}$$::jsonb,
  'mc','short',$${"concepts":["institutionel tillid","demokratisk backsliding","legitimitet","social kapital","ond cirkel","polarisering"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Bør flertalsbeslutninger have konstitutionelle grænser — og hvad er det stærkeste argument for at flertallet IKKE altid bør have det sidste ord?","options":["Ja — fordi ubegrænset flertalsdemokrati kan producere demokratisk tyranni: et flertal kan stemme for at fratage mindretallet grundlæggende rettigheder. Konstitutionelle skranker beskytter mindretalsrettigheder mod flertallets vilkårlighed — og dette er præcis hvad retsstaten indebærer som nødvendigt supplement til demokratiet","Nej — flertallet skal altid have det sidste ord fordi folkesuvereniteten er absolut og enhver konstitutionel begrænsning af flertallets vilje er anti-demokratisk per definition","Grænser er kun nødvendige i nye demokratier — modne demokratier kan stole på at flertallet spontant og konsekvent respekterer mindretallet uden formelle skranker","Konstitutionelle grænser er udelukkende skabt for at beskytte eliternes privilegier og ikke mindretals rettigheder — de er et magtbevarende redskab for dem der allerede har magt"],"correct":"Ja — fordi ubegrænset flertalsdemokrati kan producere demokratisk tyranni: et flertal kan stemme for at fratage mindretallet grundlæggende rettigheder. Konstitutionelle skranker beskytter mindretalsrettigheder mod flertallets vilkårlighed — og dette er præcis hvad retsstaten indebærer som nødvendigt supplement til demokratiet","accepted_answers":["Ja — fordi ubegrænset flertalsdemokrati kan producere demokratisk tyranni: et flertal kan stemme for at fratage mindretallet grundlæggende rettigheder. Konstitutionelle skranker beskytter mindretalsrettigheder mod flertallets vilkårlighed — og dette er præcis hvad retsstaten indebærer som nødvendigt supplement til demokratiet"],"review_text":"Alexis de Tocqueville identificerede 'tyranniets flertal' i Democracy in America (1835): demokrati kan producere en majoritetsdiktaturs dynamik. James Madisons Federalist No. 51 designede USA's magtadskillelse netop for at forhindre flertalstyranni. Historiske eksempler er entydige: Nazityskland brugte demokratiske processer til at fjerne demokratiet — Ermächtigungsgesetz blev vedtaget med kvalificeret flertal i Rigsdagen i 1933. Ungarns Fidesz har brugt parlamentariske flertal til systematisk at svække domstole og medieuafhængigged. Konstitutionel beskyttelse af mindretalsrettigheder er ikke anti-demokratisk — det er demokratiets selvforsvar mod sin egen potentielle degenerering til majoritetsdespotisme."}$$::jsonb,
  'mc','short',$${"concepts":["flertalstyranni","konstitutionelle skranker","mindretalsrettigheder","folkesuvereniteten","retsstaten","Tocqueville"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad adskiller et ægte demokrati fra et 'electoralt autoritarisme' — og er regelmæssige valg tilstrækkelige til at sikre demokratisk legitimitet?","options":["Valg er nødvendige men ikke tilstrækkelige: demokratisk legitimitet kræver også pressefrihed, uafhængige domstole, reelt politisk opposition og beskyttelse af borgerrettigheder mellem valg. Lande som Rusland og Venezuela afholder valg men mangler disse supplementer — og er derfor electorale autokratier snarere end demokratier","Regelmæssige og formelt korrekte valg er fuldt tilstrækkelige til demokratisk legitimitet — alt hvad der sker mellem valg er politisk sekundært","Demokratisk legitimitet kræver fuldstændig lighed i politiske ressourcer og intet valg kan være legitimt før fuldstændig materiel lighed er opnået","Legitimitet er et forældet normativt begreb — moderne demokratier defineres udelukkende af høj valgdeltagelse og procedurelt korrekte afstemninger"],"correct":"Valg er nødvendige men ikke tilstrækkelige: demokratisk legitimitet kræver også pressefrihed, uafhængige domstole, reelt politisk opposition og beskyttelse af borgerrettigheder mellem valg. Lande som Rusland og Venezuela afholder valg men mangler disse supplementer — og er derfor electorale autokratier snarere end demokratier","accepted_answers":["Valg er nødvendige men ikke tilstrækkelige: demokratisk legitimitet kræver også pressefrihed, uafhængige domstole, reelt politisk opposition og beskyttelse af borgerrettigheder mellem valg. Lande som Rusland og Venezuela afholder valg men mangler disse supplementer — og er derfor electorale autokratier snarere end demokratier"],"review_text":"Steven Levitsky og Lucan Ways How Democracies Die og Larry Diamonds begreb 'electoral authoritarianism' præciserer distinktionen. Et electoralt autoritærstyre afholder valg men kontrollerer medierne, undertrykker oppositionen og bruger statsapparatet til at favorisere den siddende regering. Rusland under Putin, Venezuela under Maduro og Ungarn under Orbán afholder alle valg — men valgudfaldene er strukturelt forudbestemt. Robert Dahl definerede polyarki som kombinationen af reel valgmulighed og fundamentale borgerlige friheder. Valg er den nødvendige men aldrig tilstrækkelige betingelse — demokrati er et system af gensidigt understøttende institutioner, ikke blot en procedure der gentages hvert fjerde år."}$$::jsonb,
  'mc','short',$${"concepts":["electoral authoritarianism","demokratisk legitimitet","polyarki","Dahl","pressefrihed","Levitsky"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det stærkeste argument MOD at udvide direkte demokrati via folkeafstemninger som supplement til repræsentativt demokrati?","options":["At direkte demokrati kan udnyttes af populistiske ledere til at omgå parlamentarisk kontrol og mindretalsrettigheder: folkeafstemninger reducerer komplekse politiske spørgsmål til ja/nej og fjerner den deliberative fase der sker i parlamentet — Brexit-afstemningen viser at et flertal kan stemme for noget med konsekvenser der ikke var fuldt forstået og med massiv misinformation i kampagnen","At folk er for uvidende til at stemme og alle vigtige beslutninger bør overlades til teknokratiske eksperter der besidder den nødvendige sagkundskab","At repræsentativt demokrati altid producerer bedre beslutninger end direkte demokrati fordi folkevalgte politikere automatisk er mere informerede end befolkningen","At folkeafstemninger er uproblematiske og det stærkeste argument imod er politikeres selvinteresse i at beholde beslutningsmagten hos sig selv"],"correct":"At direkte demokrati kan udnyttes af populistiske ledere til at omgå parlamentarisk kontrol og mindretalsrettigheder: folkeafstemninger reducerer komplekse politiske spørgsmål til ja/nej og fjerner den deliberative fase der sker i parlamentet — Brexit-afstemningen viser at et flertal kan stemme for noget med konsekvenser der ikke var fuldt forstået og med massiv misinformation i kampagnen","accepted_answers":["At direkte demokrati kan udnyttes af populistiske ledere til at omgå parlamentarisk kontrol og mindretalsrettigheder: folkeafstemninger reducerer komplekse politiske spørgsmål til ja/nej og fjerner den deliberative fase der sker i parlamentet — Brexit-afstemningen viser at et flertal kan stemme for noget med konsekvenser der ikke var fuldt forstået og med massiv misinformation i kampagnen"],"review_text":"Jan-Werner Müller viser i What is Populism? at populistiske bevægelser systematisk anvender direkte demokrati som redskab til at omgå institutionel kontrol. Brexit (2016) illustrerer problemet: en 52/48 afstemning traf en irreversibel beslutning om fundamentale samfundsforhold under massiv kampagnemisinformation. Historisk er folkeafstemninger brugt til at legitimere autoritære regimer: Napoleons plebiscitter og Hitlers folkeafstemninger efter magtovertagelsen. Deliberativt demokratiteori (Habermas) betoner at god demokratisk beslutning kræver tid til informeret drøftelse — ikke blot taloptælling. Det parlamentariske systems styrke er netop den deliberative fase: udvalgsbehandling, høringer, kompromisforhandling og mulighed for omformulering. Direkte demokrati er ikke uberettiget men kræver stærke rammebetingelser for at fungere demokratisk forsvarligt."}$$::jsonb,
  'mc','short',$${"concepts":["direkte demokrati","repræsentativt demokrati","folkeafstemning","Brexit","deliberation","Habermas"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er uafhængige domstole der kan tilsidesætte parlamentsbeslutninger anti-demokratiske fordi dommerne ikke er folkevalgte?","options":["Nej — domstolenes demokratiske funktion er præcis at beskytte mindretallet mod flertallets overgreb og grundloven mod politisk opportunisme. Dommernes uafhængigged er demokratiets strukturelle selvforsvar, ikke dets modsætning — og at dommere er udnævnte frem for valgte er designet til at isolere dem fra kortsigtede politiske pres der kan kompromittere retsstaten","Ja — demokratisk legitimitet kræver at alle magtudøvere er folkevalgte og domstolsprøvelse af parlamentets beslutninger er per definition anti-demokratisk","Domstole er hverken demokratiske eller anti-demokratiske — de er rent tekniske institutioner der anvender regler uden nogen politisk funktion","Uafhængige domstole er kun legitime i lande med angelsaksisk retssystem og er uden relevans for kontinentale parlamentariske demokratier"],"correct":"Nej — domstolenes demokratiske funktion er præcis at beskytte mindretallet mod flertallets overgreb og grundloven mod politisk opportunisme. Dommernes uafhængigged er demokratiets strukturelle selvforsvar, ikke dets modsætning — og at dommere er udnævnte frem for valgte er designet til at isolere dem fra kortsigtede politiske pres der kan kompromittere retsstaten","accepted_answers":["Nej — domstolenes demokratiske funktion er præcis at beskytte mindretallet mod flertallets overgreb og grundloven mod politisk opportunisme. Dommernes uafhængigged er demokratiets strukturelle selvforsvar, ikke dets modsætning — og at dommere er udnævnte frem for valgte er designet til at isolere dem fra kortsigtede politiske pres der kan kompromittere retsstaten"],"review_text":"Alexander Hamiltons Federalist No. 78 formulerede det klassiske argument: domstolene er 'the least dangerous branch' og deres uafhængigged er ikke demokratiets modpol men dets vagt. Konstitutionelt demokrati adskiller sig fra rent majoritetsstyre ved præcis at indsætte juridiske skranker for flertallets magt. Polens PiS og Ungarns Fidesz forsøgte begge at udvide politisk kontrol over domstolene — EU reagerede med retsstatsmekanismer fordi domstolsafhængigged underminerer det fælles retsgrundlag. Dommeres legitimitet er procedural, ikke electoral: de er legitime fordi de anvender regler vedtaget demokratisk via en procedure der er accepteret af alle parter — ikke fordi de er valgt af et flertal der kan afsætte dem ved næste valg."}$$::jsonb,
  'mc','short',$${"concepts":["domstolsuafhængigged","retsstaten","konstitutionelt demokrati","Hamilton","mindretalsrettigheder","domstolsprøvelse"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er kerneargumentet for magtadskillelse — og hvad sker der historisk med demokratier der opgiver det?","options":["Kerneargumentet er at koncentreret magt korrumperer: Montesquieus indsigt var at magt kun kan begrænses af magt — lovgivende, udøvende og dømmende magt skal balancere hinanden for at forhindre tyranni. Historisk kollaps: Hitlers Ermächtigungsgesetz i 1933 samlede al lovgivningsmagt i regeringen og det var dette første skridt der muliggjorde de øvrige angreb på demokratiet","Magtadskillelse er udelukkende et angelsaksisk princip uden relevans for parlamentariske demokratier som Danmark der har ministeransvar og folketing","Magtadskillelse er primært designet til at bremse regeringseffektivitet og er i praksis et anti-demokratisk princip der giver uvalgte institutioner magt over folkevalgte","Historien viser at demokratier uden magtadskillelse faktisk er mere stabile og effektive end dem med — den er en angelsaksisk ideologisk eksport"],"correct":"Kerneargumentet er at koncentreret magt korrumperer: Montesquieus indsigt var at magt kun kan begrænses af magt — lovgivende, udøvende og dømmende magt skal balancere hinanden for at forhindre tyranni. Historisk kollaps: Hitlers Ermächtigungsgesetz i 1933 samlede al lovgivningsmagt i regeringen og det var dette første skridt der muliggjorde de øvrige angreb på demokratiet","accepted_answers":["Kerneargumentet er at koncentreret magt korrumperer: Montesquieus indsigt var at magt kun kan begrænses af magt — lovgivende, udøvende og dømmende magt skal balancere hinanden for at forhindre tyranni. Historisk kollaps: Hitlers Ermächtigungsgesetz i 1933 samlede al lovgivningsmagt i regeringen og det var dette første skridt der muliggjorde de øvrige angreb på demokratiet"],"review_text":"Montesquieu formulerede i De l'Esprit des Lois (1748) at politisk frihed forudsætter at statsmagten er delt — en magt der ikke er delt er en potentielt tyrannisk magt. Madisons checks and balances i USA's forfatning tilføjede at hvert magtcenter kan bremse de andre. Det historiske mønster for demokratisk kollaps bekræfter teorien: Ermächtigungsgesetz (marts 1933) overdrog lovgivningsmagt til Kabinettet og eliminerede parlamentarisk kontrol. Erdogans præsidentialsystem (2017) koncentrerede magt og svækkede parlamentet. Chavez/Maduro underordnede systematisk domstole og parlament under præsidentmagten i Venezuela. Magtadskillelse er ikke en bureaukratisk hindring for effektivitet — det er den mekanisme der forhindrer midlertidig politisk succes i at omformes til permanent magtmonopol."}$$::jsonb,
  'mc','short',$${"concepts":["magtadskillelse","Montesquieu","Ermächtigungsgesetz","checks and balances","tyranni","demokratisk kollaps"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er populisme en trussel mod demokratiet eller et legitimt udtryk for det — og hvad afgør hvilket det er?","options":["Det afhænger af om populismen respekterer demokratiets procedurelle og substantielle regler: populisme som påstand om at repræsentere det sande folk mod en korrupt elite er en legitim demokratisk kritik — men når populistiske bevægelser underminerer domstolsuafhængigged, pressefrihed og valgintegritet er de ikke demokratiske men illiberale. Grænsen går ved institutionel respekt","Populisme er altid og per definition anti-demokratisk fordi det forenkler komplekse spørgsmål til et simpelt folk-mod-elite-skema der er intellektuelt uærligt","Populisme er altid legitimt demokratisk udtryk fordi det afspejler folkestemningen mere direkte og ufortyndet end etablerede partier og parlamentarisk politik","Populisme er et rent akademisk begreb uden analytisk anvendelighed i virkelig politik og bør ikke bruges som analytisk kategori"],"correct":"Det afhænger af om populismen respekterer demokratiets procedurelle og substantielle regler: populisme som påstand om at repræsentere det sande folk mod en korrupt elite er en legitim demokratisk kritik — men når populistiske bevægelser underminerer domstolsuafhængigged, pressefrihed og valgintegritet er de ikke demokratiske men illiberale. Grænsen går ved institutionel respekt","accepted_answers":["Det afhænger af om populismen respekterer demokratiets procedurelle og substantielle regler: populisme som påstand om at repræsentere det sande folk mod en korrupt elite er en legitim demokratisk kritik — men når populistiske bevægelser underminerer domstolsuafhængigged, pressefrihed og valgintegritet er de ikke demokratiske men illiberale. Grænsen går ved institutionel respekt"],"review_text":"Jan-Werner Müllers What is Populism? definerer populisme som en moralsk skelnen mellem det korrupte etablissement og det sande folk — og hævder at populisterne alene repræsenterer dette folk. Denne struktur er ikke i sig selv anti-demokratisk: demokratisk kritik af eliter og krav om bedre repræsentation er legitime. Det er handlingerne der afgør spørgsmålet. Orbáns Fidesz begyndte som et liberalt studentparti, vandt demokratisk valg, og demonterede derefter systematisk pressefrihed, domstolsuafhængigged og valglovgivning på en måde der sikrede fremtidige valgsejre. Levitsky og Ziblatt kalder det 'democratic backsliding': det starter med fair valg og ender med at fairness er elimineret. Populisme er ikke en sygdom der kræver kur — det er et politisk symptom der kræver diagnose."}$$::jsonb,
  'mc','short',$${"concepts":["populisme","illiberalt demokrati","Müller","Orbán","democratic backsliding","institutionel respekt"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er mediernes demokratiske funktion — og hvad sker der med demokratiet når medierne er ensrettede eller systematisk partiske?","options":["Medier er demokratiets fjerde statsmagt: de informerer borgerne, holder magthavere ansvarlige via watchdog-funktionen og skaber det fælles faktuelle grundlag som deliberativt demokrati kræver. Ensrettede medier underminerer præcis disse funktioner: borgerne informeres selektivt, magthavere skærmes fra kritik og den fælles faktuelle platform eroderer med polarisering og institutionel mistillid som konsekvens","Medierne i et demokrati bør primært afspejle flertallets meninger og ikke kritisere den siddende regering der er demokratisk valgt og dermed har folkelig mandat","Mediernes rolle er rent kommerciel — de er virksomheder der konkurrerer om brugernes opmærksomhed og har ingen særlig demokratisk funktion eller ansvar","Partiske medier styrker demokratiet ved at mobilisere vælgerne mere effektivt end neutrale medier der producerer politisk ligegyldighed"],"correct":"Medier er demokratiets fjerde statsmagt: de informerer borgerne, holder magthavere ansvarlige via watchdog-funktionen og skaber det fælles faktuelle grundlag som deliberativt demokrati kræver. Ensrettede medier underminerer præcis disse funktioner: borgerne informeres selektivt, magthavere skærmes fra kritik og den fælles faktuelle platform eroderer med polarisering og institutionel mistillid som konsekvens","accepted_answers":["Medier er demokratiets fjerde statsmagt: de informerer borgerne, holder magthavere ansvarlige via watchdog-funktionen og skaber det fælles faktuelle grundlag som deliberativt demokrati kræver. Ensrettede medier underminerer præcis disse funktioner: borgerne informeres selektivt, magthavere skærmes fra kritik og den fælles faktuelle platform eroderer med polarisering og institutionel mistillid som konsekvens"],"review_text":"Walter Lippmanns Public Opinion (1922) og Habermas teori om den offentlige sfære understreger begge mediernes centrale demokratiske funktion som producenter af det informationsrum borgerne tænker og beslutter inden for. Lande med høj pressefrihed (Reporters Without Borders) har generelt stærkere demokratiske institutioner. Ungarn er det tydeligste europæiske eksempel: Orbán-venlige oligarker opkøbte de fleste ungarske medier og skabte et medielandskab der strukturelt favoriserer regeringen — EU's mediefrihedsindeks placerer Ungarn lavest i EU. Sociale mediers algoritmisk drevne ekkokamre udgør en ny dimension: demokratiet kræver et minimum af fælles faktuelle grundlag for at deliberation er meningsfuld. Ensretning underminerer netop dette."}$$::jsonb,
  'mc','short',$${"concepts":["mediefrihed","fjerde statsmagt","watchdog","Habermas","offentlig sfære","ensrettede medier"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Har ytringsfrihed absolutte grænser — og hvad er det stærkeste argument for at begrænse hadefuld tale?","options":["Ytringsfrihed er ikke absolut og det stærkeste argument for at begrænse hadefuld tale er konkret reel skade: ytringer der systematisk dehumaniserer minoriteter skaber det sociale klima hvori diskrimination og vold normaliseres. Rwanda 1994 viste at radioens hadepropaganda var direkte medvirkende til folkemordets eskalering — forebyggelse af alvorlig reel skade er en legitim begrænsning af ytringsfriheden","Ytringsfrihed er absolut og enhver begrænsning udgør en farlig glidebane mod censur der er langt mere skadelig for demokratiet end den tale der forsøges begrænset","Hate speech er udelukkende et problem i USA og den amerikanske debat har ingen relevans for europæiske demokratier med en anden retskultur og tradition","Ytringsfrihed bør primært beskytte politisk tale og kunst mens al anden kommunikation kan reguleres frit af de demokratisk valgte myndigheder"],"correct":"Ytringsfrihed er ikke absolut og det stærkeste argument for at begrænse hadefuld tale er konkret reel skade: ytringer der systematisk dehumaniserer minoriteter skaber det sociale klima hvori diskrimination og vold normaliseres. Rwanda 1994 viste at radioens hadepropaganda var direkte medvirkende til folkemordets eskalering — forebyggelse af alvorlig reel skade er en legitim begrænsning af ytringsfriheden","accepted_answers":["Ytringsfrihed er ikke absolut og det stærkeste argument for at begrænse hadefuld tale er konkret reel skade: ytringer der systematisk dehumaniserer minoriteter skaber det sociale klima hvori diskrimination og vold normaliseres. Rwanda 1994 viste at radioens hadepropaganda var direkte medvirkende til folkemordets eskalering — forebyggelse af alvorlig reel skade er en legitim begrænsning af ytringsfriheden"],"review_text":"John Stuart Mills harm principle i On Liberty (1859) er det klassiske fundament: frihed begrænses kun af skade på andre. Hate speech-debatten er en kalibreringsdebat om hvornår verbal skade er reel nok til at begrunde begrænsning. Den Europæiske Menneskerettighedsdomstol anerkender at artikel 10 (ytringsfrihed) kan begrænses under artikel 17 — Holocaust-benægtelse og systematisk dehumanisering er undtaget beskyttelse. Rwanda-genocidet (1994) er det mest dokumenterede eksempel: Radio Mille Collines' systematiske fremstilling af tutsierne som kakerlakker var empirisk forbundet med øget vold. Debatten har et reelt dilemma: begrænsninger kan misbruges til at undertrykke legitim kritik — balance er nødvendig. Men det absolutte ytringsfriheds-argument ignorerer at systematisk dehumanisering har reelle menneskelige ofre."}$$::jsonb,
  'mc','short',$${"concepts":["ytringsfrihed","hate speech","harm principle","Mill","Rwanda","ECHR artikel 10"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er det kohærent at hævde borgerrettigheder uden at acceptere tilsvarende borgerpligter — og hvad er forholdet mellem rettigheder og ansvar i demokratiet?","options":["Rettigheder og pligter er gensidigt konstituerende i et demokratisk samfund: retten til ytringsfrihed forudsætter at man ikke undergraver andres ret til at deltage, stemmeretten forudsætter at valgresultater respekteres og retten til domstolsbeskyttelse forudsætter at man accepterer domstolenes autoritet. Rettigheder uden tilsvarende pligter undergraver det fællesskab der beskytter rettighederne","Rettigheder er absolutte og ubetingede — de eksisterer uanset om borgeren opfylder nogen pligter og kan ikke betinges af adfærd","Pligter er primært et autoritært begreb der bruges til at begrænse rettigheder og bør afskaffes i liberale demokratier til fordel for rent individbaserede rettigheder","Forholdet mellem rettigheder og pligter er rent juridisk og har ingen etisk eller demokratisk dimension ud over hvad lovgivningen eksplicit fastsætter"],"correct":"Rettigheder og pligter er gensidigt konstituerende i et demokratisk samfund: retten til ytringsfrihed forudsætter at man ikke undergraver andres ret til at deltage, stemmeretten forudsætter at valgresultater respekteres og retten til domstolsbeskyttelse forudsætter at man accepterer domstolenes autoritet. Rettigheder uden tilsvarende pligter undergraver det fællesskab der beskytter rettighederne","accepted_answers":["Rettigheder og pligter er gensidigt konstituerende i et demokratisk samfund: retten til ytringsfrihed forudsætter at man ikke undergraver andres ret til at deltage, stemmeretten forudsætter at valgresultater respekteres og retten til domstolsbeskyttelse forudsætter at man accepterer domstolenes autoritet. Rettigheder uden tilsvarende pligter undergraver det fællesskab der beskytter rettighederne"],"review_text":"T.H. Marshalls teori om citizenship (1950) skelner mellem civile, politiske og sociale rettigheder og implicerer at citizenship er et gensidigt forhold: staten garanterer rettigheder, borgeren accepterer pligter som lovlydighed, skattebetaling og civilt engagement. Den republikanske tradition (Cicero, Rousseau, Arendt) betoner stærkere: politisk frihed er ikke en privat ret men en kollektiv praksis der kræver aktiv deltagelse og ansvar. Det politiske fritrytterproblem er reelt: borgere der nyder demokratiets frugter men afviser enhver forpligtelse underminerer det reciprocitetsprincip som den sociale kontrakt bygger på. Rettigheder og pligter er ikke perfecte korrelater i detaljen, men ingen stabil demokratisk orden er mulig uden minimumsacceptance af begge sider af borgerkontrakten."}$$::jsonb,
  'mc','short',$${"concepts":["rettigheder og pligter","citizenship","Marshall","social kontrakt","reciprocitet","borgerpligt"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det afgørende princip der begrunder beskyttelse af mindretal i et demokrati — og hvad er konsekvensen hvis dette princip afvises?","options":["Princippet er at demokratisk legitimitet bygger på beskyttelse af alle borgeres grundlæggende rettigheder og ikke blot flertallets præferencer. Et demokrati der kan fratage et mindretal grundlæggende rettigheder ved ren stemmetælling er ikke et liberalt demokrati men et majoritetsstyre — og historisk har sådanne systemer produceret apartheid, segregation og folkedrab","Mindretalsrettigheder er unødvendige i demokratier fordi flertallet i et fungerende demokrati altid spontant vil handle retfærdigt og hensynsfuldt mod mindretallet","Mindretalsrettigheder undergraver demokratiets kerneprincip fordi de tillader dem med færre stemmer at blokere flertallets demokratisk udtrykte vilje","Mindretalsrettigheder er kun relevante for etniske og religiøse mindretal og har ingen bredere demokratisk principiel funktion"],"correct":"Princippet er at demokratisk legitimitet bygger på beskyttelse af alle borgeres grundlæggende rettigheder og ikke blot flertallets præferencer. Et demokrati der kan fratage et mindretal grundlæggende rettigheder ved ren stemmetælling er ikke et liberalt demokrati men et majoritetsstyre — og historisk har sådanne systemer produceret apartheid, segregation og folkedrab","accepted_answers":["Princippet er at demokratisk legitimitet bygger på beskyttelse af alle borgeres grundlæggende rettigheder og ikke blot flertallets præferencer. Et demokrati der kan fratage et mindretal grundlæggende rettigheder ved ren stemmetælling er ikke et liberalt demokrati men et majoritetsstyre — og historisk har sådanne systemer produceret apartheid, segregation og folkedrab"],"review_text":"James Madisons distinction i Federalist No. 10 mellem demokrati (direkte flertalsstyre) og republik (repræsentativt system med konstitutionelle skranker) præciserer netop dette: ubeskyttet flertalsstyre er demokrati i en potentielt farlig form. Historiske eksempler er entydige: Sydafrikas apartheid var understøttet af hvid vælgermajoritet, USA's Jim Crow-love var lovgivningsmæssigt støttet af sydstaternes flertal, Rwandas folkedrab var ideologisk understøttet af hutumajoritetens nationale bevægelse. Konstitutionelle garantier for mindretalsrettigheder (ECHR, grundlovssikrede rettigheder) er designet til at gøre disse rettigheder immune overfor flertallets skiftende præferencer. Demokrati uden mindretalsrettigheder er ikke en stærkere form for demokrati — det er et system på vej mod majoritetstyranni."}$$::jsonb,
  'mc','short',$${"concepts":["mindretalsrettigheder","majoritetsstyre","Madison","apartheid","liberalt demokrati","konstitutionel garanti"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den primære etiske spænding i afvejningen af national sikkerhed og borgerlige frihedsrettigheder — og hvad viser historien om denne afvejning?","options":["Spændingen er at sikkerhedsforanstaltninger typisk begrænser præcis de rettigheder der er demokratiets grundlag — og historien viser at ekstraordinære magtbeføjelser indført i krisesituationer sjældent afskaffes efter krisen: USA PATRIOT Act efter 11. september og COVID-19 undtagelsestilstande illustrerer begge at midlertidige begrænsninger har tendens til at permanentisere sig","National sikkerhed og borgerlige rettigheder er fuldt kompatible og der er ingen reel spænding — begge kan maksimeres samtidigt ved kloge politiske valg","I sikkerhedskriser bør borgerlige rettigheder altid vige for statens sikkerhedsbehov uden yderligere etisk afvejning","Borgerlige rettigheder bør aldrig begrænses under nogen omstændighedstype uanset sikkerhedssituation og trusselsgrad"],"correct":"Spændingen er at sikkerhedsforanstaltninger typisk begrænser præcis de rettigheder der er demokratiets grundlag — og historien viser at ekstraordinære magtbeføjelser indført i krisesituationer sjældent afskaffes efter krisen: USA PATRIOT Act efter 11. september og COVID-19 undtagelsestilstande illustrerer begge at midlertidige begrænsninger har tendens til at permanentisere sig","accepted_answers":["Spændingen er at sikkerhedsforanstaltninger typisk begrænser præcis de rettigheder der er demokratiets grundlag — og historien viser at ekstraordinære magtbeføjelser indført i krisesituationer sjældent afskaffes efter krisen: USA PATRIOT Act efter 11. september og COVID-19 undtagelsestilstande illustrerer begge at midlertidige begrænsninger har tendens til at permanentisere sig"],"review_text":"ECHR artikel 15 tillader undtagelser fra rettigheder i nødsituationer — men kræver at begrænsningerne er proportionale og tidsbegrænsede. Den historiske tendens er imidlertid at midlertidige undtagelser permanentiseres: USA PATRIOT Act (2001) vedtaget som midlertidig antiterrorforanstaltning indeholder beføjelser der stadig er aktive årtier senere. Edward Snowdens afsløringer viste at NSA's masseovervågning opererede langt ud over de juridisk godkendte rammer. Det demokratiske dilemma er institutionelt: hvem kontrollerer dem der kontrollerer for sikkerhed? Svaret er uafhængig parlamentarisk oversight og domstolskontrol — men disse er præcis de institutioner som sikkerhedsapparaterne har incitament til at begrænse. Spændingen er ikke teknisk men strukturel."}$$::jsonb,
  'mc','short',$${"concepts":["national sikkerhed","borgerrettigheder","PATRIOT Act","proportionalitet","permanentisering","overvågning"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Udgør systematisk misinformation og desinformation en strukturel trussel mod demokratisk beslutningstagning — og hvad er den bedste demokratiske respons?","options":["Ja — demokratisk deliberation forudsætter et minimum af fælles faktuel grundlag: systematisk desinformation undergraver borgernes evne til at vurdere politiske alternativer og træffe informerede valg. Den bedste demokratiske respons kombinerer mediekundskab i uddannelse, uafhængig faktachecking og platformsregulering — men undgår statslig censur der ville producere et andet og mindst ligeså alvorligt problem","Misinformation er ikke et demokratisk problem fordi borgerne altid kan skelne sandt fra falsk hvis de er motiverede og kritisk tænkende","Staten bør have fuldt ansvar for at definere og fjerne al misinformation fra offentlig kommunikation — det er demokratiets pligt at sikre borgerne modtager korrekt information","Demokratier bør ignorere misinformationsproblemer fordi det frie idémarked automatisk selekterer sande informationer over falske via konkurrence"],"correct":"Ja — demokratisk deliberation forudsætter et minimum af fælles faktuel grundlag: systematisk desinformation undergraver borgernes evne til at vurdere politiske alternativer og træffe informerede valg. Den bedste demokratiske respons kombinerer mediekundskab i uddannelse, uafhængig faktachecking og platformsregulering — men undgår statslig censur der ville producere et andet og mindst ligeså alvorligt problem","accepted_answers":["Ja — demokratisk deliberation forudsætter et minimum af fælles faktuel grundlag: systematisk desinformation undergraver borgernes evne til at vurdere politiske alternativer og træffe informerede valg. Den bedste demokratiske respons kombinerer mediekundskab i uddannelse, uafhængig faktachecking og platformsregulering — men undgår statslig censur der ville producere et andet og mindst ligeså alvorligt problem"],"review_text":"Shoshana Zuboffs Surveillance Capitalism viser at platformsøkonomiernes forretningsmodel systematisk belønner engagement — og negativt emotionelt indhold driver mere engagement end nøgtern faktainformation. Cambridge Analytica-skandalen (2018) dokumenterede at mikromålrettet politisk misinformation i stor skala var mulig og effektiv. Habermas deliberative demokratiteori kollapser hvis borgerne opererer i fundamentalt adskilte informationsbobler. Faktachecking er nødvendigt men ikke tilstrækkeligt, platformsregulering (EU's Digital Services Act) søger balance, mediekundskab i grundskolen er den mest langsigtede løsning. Statskontrolleret sandhedsdefinition er modgiften der er ligeså giftig som sygdommen."}$$::jsonb,
  'mc','short',$${"concepts":["misinformation","desinformation","deliberativt demokrati","platformsregulering","mediekundskab","Digital Services Act"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad kendetegner demokratisk backsliding — og hvad adskiller det fra tidligere tiders klassiske militærkup?","options":["Demokratisk backsliding sker indefra og via demokratiske processer: i modsætning til klassiske militærkup der ophæver forfatningen med magt eroderer backsliding institutioner gradvist via valglovændringer, domstolspakninger og mediekoncentration. Det er sværere at stoppe fordi hvert enkelt skridt isoleret set ser relativt harmløst ud og den formelle demokratiske facade opretholdes","Demokratisk backsliding er identisk med militærkup — begge fjerner demokratiet med magt og åben konfrontation med de eksisterende institutioner","Demokratisk backsliding er et rent akademisk begreb der ikke beskriver virkelige politiske processer og ikke bør bruges i politisk analyse","Demokratisk backsliding er altid reversibelt via de næste valg og udgør ingen langsigtet strukturel trussel mod etablerede demokratier"],"correct":"Demokratisk backsliding sker indefra og via demokratiske processer: i modsætning til klassiske militærkup der ophæver forfatningen med magt eroderer backsliding institutioner gradvist via valglovændringer, domstolspakninger og mediekoncentration. Det er sværere at stoppe fordi hvert enkelt skridt isoleret set ser relativt harmløst ud og den formelle demokratiske facade opretholdes","accepted_answers":["Demokratisk backsliding sker indefra og via demokratiske processer: i modsætning til klassiske militærkup der ophæver forfatningen med magt eroderer backsliding institutioner gradvist via valglovændringer, domstolspakninger og mediekoncentration. Det er sværere at stoppe fordi hvert enkelt skridt isoleret set ser relativt harmløst ud og den formelle demokratiske facade opretholdes"],"review_text":"Levitsky og Ziblatt How Democracies Die (2018) dokumenterer mønsteret: moderne demokratiske kollaps starter ikke med tanke i gaderne men med valgte ledere der anvender demokratiske institutioner til at eliminere demokratiets konkurrencevilkår. Ungarn er det mest analyserede europæiske eksempel: Orbán vandt superflertal i 2010, ændrede valglovgivning for at favorisere store partier, omformede mediesektoren via oligarkvenlighed, ændrede domstolenes sammensætning og omdefinerede grundloven — alt imens formelle valg fortsættes. Hvert enkelt skridt var juridisk muligt. Samlet er Ungarn nu af Freedom House klassificeret som 'partly free'. Backsliding er gradvis og kumulativ — og netop derfor strukturelt sværere at modvirke end et åbent kupforsøg."}$$::jsonb,
  'mc','short',$${"concepts":["democratic backsliding","Levitsky","Ziblatt","Orbán","institutionel erosion","gradvis autoritarisme"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er politisk polarisering altid en trussel mod demokratiet — eller kan der sondres mellem former for polarisering med forskellige demokratiske konsekvenser?","options":["Affektiv polarisering er demokratisk farlig mens ideologisk polarisering kan være sund: affektiv polarisering (dyb gensidig fjendtlighed og mistillid mellem politiske lejre uanset saglige uenigheder) underminerer kompromis og parlamentarisk funktion. Ideologisk polarisering (klare valg mellem reelle alternativer) kan styrke demokratisk engagement. Skelnen er analytisk afgørende","Polarisering er altid demokratisk farlig fordi demokratiet kræver enighed og konsensus for at fungere og producere stabile beslutninger","Polarisering er altid demokratisk sund fordi politisk kamp afklarer ideologiske modsætninger og giver vælgerne tydeligere valg","Polarisering er irrelevant for demokratiets funktionsevne — det er et rent kulturelt og sociologisk fænomen uden politiske konsekvenser"],"correct":"Affektiv polarisering er demokratisk farlig mens ideologisk polarisering kan være sund: affektiv polarisering (dyb gensidig fjendtlighed og mistillid mellem politiske lejre uanset saglige uenigheder) underminerer kompromis og parlamentarisk funktion. Ideologisk polarisering (klare valg mellem reelle alternativer) kan styrke demokratisk engagement. Skelnen er analytisk afgørende","accepted_answers":["Affektiv polarisering er demokratisk farlig mens ideologisk polarisering kan være sund: affektiv polarisering (dyb gensidig fjendtlighed og mistillid mellem politiske lejre uanset saglige uenigheder) underminerer kompromis og parlamentarisk funktion. Ideologisk polarisering (klare valg mellem reelle alternativer) kan styrke demokratisk engagement. Skelnen er analytisk afgørende"],"review_text":"Lilliana Masons Uncivil Agreement (2018) dokumenterer at affektiv polarisering i USA er steget markant siden 1990erne — ikke fordi folk er mere ideologisk uenige om politik, men fordi politisk identitet er smeltet sammen med kulturel, religiøs og racial identitet. Jonathan Haidt i The Righteous Mind viser at moral-emotionelle reaktioner kan gøre rationel politisk diskussion umulig. Kompromis er demokratiets operationelle mekanisme — og affektiv polarisering gør kompromis til forræderi mod sin egen gruppe. Ideologisk polarisering er anderledes: skandinaviske socialdemokratiske og borgerlige modsætninger var ideologisk klare men affektivt moderate og producerede historisk velfærdsstaten via kompromis. Distinktionen er ikke blot akademisk — den afgør hvad der er behandlingens mål."}$$::jsonb,
  'mc','short',$${"concepts":["affektiv polarisering","ideologisk polarisering","kompromis","Mason","demokratisk funktion","politisk identitet"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er lav valgdeltagelse og civilt engagement primært et demokratisk legitimitetsproblem — og hvad viser forskning om hvem der ikke stemmer?","options":["Lav deltagelse er demokratisk bekymrende når den skyldes alienation eller strukturelle barrierer snarere end tilfredshed: forskning viser at lav deltagelse er systematisk skæv — lavindkomstgrupper, unge og minoriteter stemmer konsekvent sjældnere. Dette skævvrider repræsentationen strukturelt og producerer politikker der tilgodeser overrepræsenterede grupper frem for befolkningen som helhed","Lav valgdeltagelse er altid et tegn på tilfredshed med systemet og kræver ingen politisk respons — folk der er tilfredse har intet at klage over og stemmer ikke","Obligatorisk stemmepligt er den eneste legitime og effektive løsning på lav valgdeltagelse i demokratier","Demokratiets legitimitet er fuldstændig uafhængig af valgdeltagelsens niveau fordi procedurerne er formelt korrekte uanset antal stemmer afgivet"],"correct":"Lav deltagelse er demokratisk bekymrende når den skyldes alienation eller strukturelle barrierer snarere end tilfredshed: forskning viser at lav deltagelse er systematisk skæv — lavindkomstgrupper, unge og minoriteter stemmer konsekvent sjældnere. Dette skævvrider repræsentationen strukturelt og producerer politikker der tilgodeser overrepræsenterede grupper frem for befolkningen som helhed","accepted_answers":["Lav deltagelse er demokratisk bekymrende når den skyldes alienation eller strukturelle barrierer snarere end tilfredshed: forskning viser at lav deltagelse er systematisk skæv — lavindkomstgrupper, unge og minoriteter stemmer konsekvent sjældnere. Dette skævvrider repræsentationen strukturelt og producerer politikker der tilgodeser overrepræsenterede grupper frem for befolkningen som helhed"],"review_text":"Arend Lijpharts Unequal Participation: Democracy's Unresolved Dilemma (1997) dokumenterer det systematiske skæve deltagelsesmønster: rige, ældre og etnisk majoritetsgrupper stemmer konsekvent mere end fattige, unge og minoriteter. Politiske systemer der baserer beslutninger på vælgerkorpset producerer dermed politikker der systematisk tilgodeser overrepræsenterede grupper. Stemmepligt (Australien, Belgien) øger deltagelse men rejser egne legitimitetsspørgsmål om tvang. Valglovsdesign — weekend-valg, postal voting, automatisk registrering — kan reducere strukturelle adgangsbarrierer uden tvang. Systematisk skæv deltagelse underminerer repræsentationens demokratiske kerneambition."}$$::jsonb,
  'mc','short',$${"concepts":["valgdeltagelse","skæv repræsentation","Lijphart","strukturelle barrierer","stemmepligt","demokratisk legitimitet"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er det grundlæggende filosofiske argument for at frihed-sikkerhed-afvejningen ikke har et universalt korrekt svar?","options":["Fordi de underliggende værdier — individuel frihed og kollektiv sikkerhed — er inkommensurable: de kan ikke reduceres til et fælles mål eller en neutral målestok. Afvejningen er politisk og kontekstafhængig, ikke teknisk — og i et demokrati er det præcis borgernes deliberative proces der skal afgøre afvejningen i konkrete situationer, ikke en ekspert, algoritme eller neutral myndighed","Fordi sikkerhed altid bør prioriteres da den er en logisk forudsætning for at frihed overhovedet kan udøves og nydes","Fordi frihed altid bør prioriteres da sikkerhed er et politisk skalkeskjul for autoritær kontrol og bør behandles med dyb mistillid","Fordi spørgsmålet er teknisk og bør afgøres af sikkerhedseksperter baseret på objektive trusselsanalyser uden politisk indblanding"],"correct":"Fordi de underliggende værdier — individuel frihed og kollektiv sikkerhed — er inkommensurable: de kan ikke reduceres til et fælles mål eller en neutral målestok. Afvejningen er politisk og kontekstafhængig, ikke teknisk — og i et demokrati er det præcis borgernes deliberative proces der skal afgøre afvejningen i konkrete situationer, ikke en ekspert, algoritme eller neutral myndighed","accepted_answers":["Fordi de underliggende værdier — individuel frihed og kollektiv sikkerhed — er inkommensurable: de kan ikke reduceres til et fælles mål eller en neutral målestok. Afvejningen er politisk og kontekstafhængig, ikke teknisk — og i et demokrati er det præcis borgernes deliberative proces der skal afgøre afvejningen i konkrete situationer, ikke en ekspert, algoritme eller neutral myndighed"],"review_text":"Isaiah Berlins Two Concepts of Liberty (1958) etablerede det filosofiske fundament: negativ frihed (frihed fra indblanding) og positiv frihed (frihed til selvrealisering) kan konflikte med hinanden og med sikkerhed — og der er ingen neutral metode til at rangordne dem. John Rawls konstruerede 'uvidenhedens slør' som tankeeksperiment for at nå fair principper, men selv Rawls producerede et liberalt principhierarki som ikke alle traditioner deler. Det normative pluralismeargument (Berlin, Weber) er at moderne samfund er præget af uforsonlige værdikonflikter der ikke kan løses ved ren rationalitet. Frihed-sikkerhed-afvejningen er et 'tragic choice' — demokratiets opgave er at institutionalisere den deliberative proces der legitimerer afgørelsen."}$$::jsonb,
  'mc','short',$${"concepts":["frihed vs sikkerhed","inkommensurable værdier","Berlin","normativt pluralisme","deliberativ legitimitet","tragic choice"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er der en demokratisk legitim spænding mellem princippet om politisk lighed og behovet for ekspertviden i komplekse politiske beslutninger?","options":["Ja — spændingen er reel og løsningen er institutionel: politisk lighed gælder for hvem der beslutter, ekspertise gælder for hvad beslutningstagerne informeres af. Løsningen er at styrke ekspertrådgivning til demokratiske beslutningstagere uden at overlade selve beslutningerne til eksperterne — epistocratiets alternativ eliminerer demokratiet for at løse spændingen","Der er ingen spænding — alle borgere bør have ens adgang til og forståelse af ekspertviden og demokratisk lighed og ekspertise er fuldt kompatible","Eksperter bør have vetoret over parlamentariske beslutninger i tekniske sager fordi komplekse problemstillinger ikke kan afgøres af politisk uvidende borgere","Politisk lighed er et forældet princip der bør erstattes af meritokratisk stemmefordeling baseret på uddannelsesniveau og politisk kundskab"],"correct":"Ja — spændingen er reel og løsningen er institutionel: politisk lighed gælder for hvem der beslutter, ekspertise gælder for hvad beslutningstagerne informeres af. Løsningen er at styrke ekspertrådgivning til demokratiske beslutningstagere uden at overlade selve beslutningerne til eksperterne — epistocratiets alternativ eliminerer demokratiet for at løse spændingen","accepted_answers":["Ja — spændingen er reel og løsningen er institutionel: politisk lighed gælder for hvem der beslutter, ekspertise gælder for hvad beslutningstagerne informeres af. Løsningen er at styrke ekspertrådgivning til demokratiske beslutningstagere uden at overlade selve beslutningerne til eksperterne — epistocratiets alternativ eliminerer demokratiet for at løse spændingen"],"review_text":"Jason Brennans Against Democracy (2016) er det mest radikale argument for epistokrati: komplekse politiske beslutninger bør overlades til de politisk vidende. Brennan dokumenterer systematisk politisk uvidenhed i befolkningerne. Men modstanderne (Estlund, Christiano) identificerer et fundamentalt problem: epistokatisk selektion kræver en neutral instans der afgør hvem der er kompetent — og denne instans ville have massiv politisk magt uden demokratisk kontrol. Habermas deliberative demokrati tilbyder en tredje vej: bedre institutionaliseret offentlig deliberation med ekspertdeltagelse men demokratisk legitimering. Det faktiske svar i moderne demokratier: ekspertorganer (centralbanker, epidemikommissioner, klimaråd) rådgiver men parlamentet bestemmer."}$$::jsonb,
  'mc','short',$${"concepts":["politisk lighed","epistokrati","ekspertviden","Brennan","deliberativt demokrati","ekspertrådgivning"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er det en demokratisk fejlslutning at antage at mere borgerdeltagelse altid forbedrer demokratiske beslutninger?","options":["Ja — mere deltagelse kan forværre beslutningskvaliteten hvis deltagerne er systematisk misinformerede, hvis processen er manipuleret af velorganiserede særinteresser eller hvis deltagelsesformerne belønner de mest ressourcestærke frem for de mest repræsentative. Kvaliteten af deltagelse er mindst ligeså vigtig som kvantiteten","Mere deltagelse er altid bedre i demokratiet — dette er demokratiets kernepræmis og enhver begrænsning af deltagelse er i sagens natur anti-demokratisk","Deltagelse er ligegyldig for beslutningskvalitet — gode beslutninger kræver kun ekspertviden og korrekt procedure","Høj deltagelse er altid et tegn på manipulerede processer og bør behandles med institutionel mistillid"],"correct":"Ja — mere deltagelse kan forværre beslutningskvaliteten hvis deltagerne er systematisk misinformerede, hvis processen er manipuleret af velorganiserede særinteresser eller hvis deltagelsesformerne belønner de mest ressourcestærke frem for de mest repræsentative. Kvaliteten af deltagelse er mindst ligeså vigtig som kvantiteten","accepted_answers":["Ja — mere deltagelse kan forværre beslutningskvaliteten hvis deltagerne er systematisk misinformerede, hvis processen er manipuleret af velorganiserede særinteresser eller hvis deltagelsesformerne belønner de mest ressourcestærke frem for de mest repræsentative. Kvaliteten af deltagelse er mindst ligeså vigtig som kvantiteten"],"review_text":"James Surowieckis The Wisdom of Crowds viser at store gruppers aggregerede vurderinger kan overgå eksperters under specifikke betingelser: diversitet, uafhængigged og decentralisering. Men disse betingelser er sjældent opfyldt i politisk deltagelse. Bryan Caplans The Myth of the Rational Voter dokumenterer at politisk irrationel stemmeadfærd er rationel for individet men suboptimal aggregeret. Special interest-grupper (velorganiserede, ressourcestærke) systematisk overrepræsenterer sig i deltagelsesbaserede processer — høringssvar, lobbyisme, valgkampagner. Mere deltagelse løser ikke skæv deltagelse — og kan forstærke den hvis rammebetingelserne favoriserer de allerede privilegerede. Deliberativ kvalitet, inklusivitet og informationsgrundlag er de kritiske variable."}$$::jsonb,
  'mc','short',$${"concepts":["deltagelse","Surowiecki","Caplan","særinteresser","skæv deltagelse","deliberativ kvalitet"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er karismatisk og stærk politisk ledelse nødvendigvis i konflikt med demokratiske principper?","options":["Ikke nødvendigvis — afgørende er om lederen respekterer demokratiets procedurelle og substantielle regler. Stærke ledere som Churchill, Mandela og Willy Brandt kombinerede karismatisk autoritet med institutionel respekt. Problemet opstår når ledere bruger karisma til at delegitimere de institutioner der begrænser dem — og dermed eroderer den institutionelle ramme der muliggør demokrati","Stærke ledere er altid anti-demokratiske fordi demokratiet kræver svagt, konsensuspræget og ukarismatisk lederskab","Karismatiske ledere er altid demokratiets redning fordi de kan mobilisere befolkningen mod passivitet og politisk ligegyldighed","Spørgsmålet om lederskabsstil er irrelevant for demokrati da strukturer og institutioner alene er det der afgør om et system er demokratisk"],"correct":"Ikke nødvendigvis — afgørende er om lederen respekterer demokratiets procedurelle og substantielle regler. Stærke ledere som Churchill, Mandela og Willy Brandt kombinerede karismatisk autoritet med institutionel respekt. Problemet opstår når ledere bruger karisma til at delegitimere de institutioner der begrænser dem — og dermed eroderer den institutionelle ramme der muliggør demokrati","accepted_answers":["Ikke nødvendigvis — afgørende er om lederen respekterer demokratiets procedurelle og substantielle regler. Stærke ledere som Churchill, Mandela og Willy Brandt kombinerede karismatisk autoritet med institutionel respekt. Problemet opstår når ledere bruger karisma til at delegitimere de institutioner der begrænser dem — og dermed eroderer den institutionelle ramme der muliggør demokrati"],"review_text":"Max Webers karismatisk autoritet-begreb (Economy and Society) beskriver ledere der henter legitimitet fra personlig udstråling snarere end tradition eller rationalitet. Webers analyse er neutral: karisma kan bruges til at undergrave institutioner (Hitler, Mussolini, Chavez) eller til at styrke dem. Mandela brugte sin karisma til at legitimere forsoningsprocessen og frivillig magtoverladelse til demokratiske institutioner — et af historiens stærkeste eksempler på institutionsbyggende karisma. Juan Linz i The Breakdown of Democratic Regimes viser at præsidentialisme kombineret med karismatisk lederskab systematisk øger risikoen for demokratisk kollaps — men det er kombinationen der er farlig, ikke lederskabet alene. Det demokratiske sundhedstegn er ikke at ledere er svage men at institutionerne er stærkere end lederne og overlever dem."}$$::jsonb,
  'mc','short',$${"concepts":["karismatisk lederskab","Weber","Mandela","institutionel respekt","demokratisk kollaps","stærk leder"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"democracy_power"}$$::jsonb,
  'mc_single',5,'auto',true,'democracy_power',9,5
);;
